package ca.yorku.eecs3311.coursepilot.domain.model;
import jakarta.persistence.*;
@Entity @Table(name="quiz_responses") public class QuizResponse { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="attempt_id",nullable=false) private QuizAttempt attempt; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="question_id",nullable=false) private QuizQuestion question; @Column(name="student_answer",length=3000) private String studentAnswer; @Column(nullable=false) private boolean correct; @Column(length=3000) private String feedback; protected QuizResponse(){} public QuizResponse(QuizAttempt a,QuizQuestion q,String answer,boolean correct,String feedback){attempt=a;question=q;studentAnswer=answer;this.correct=correct;this.feedback=feedback;} public Long getId(){return id;} public QuizQuestion getQuestion(){return question;} public String getStudentAnswer(){return studentAnswer;} public boolean isCorrect(){return correct;} public String getFeedback(){return feedback;} }
